                if (typeof mammoth === 'undefined') throw new Error("مكتبة Mammoth غير محملة");
                const arrayBuffer = await file.arrayBuffer();
                const result = await mammoth.extractRawText({ arrayBuffer: arrayBuffer });
                extractedText = result.value;
