      case 'addNote':
          return <AddNote onBack={handleGoHome} />;
      case 'summarizeLesson':
          return <SummarizeLesson onBack={handleGoHome} />;
      case 'createSemesterPlan':
          return <SemesterPlanner onBack={handleGoHome} />;
      case 'classSchedule':
          return <ClassSchedule onBack={handleGoHome} />;
      case 'importantDates':
          return <ImportantDates onBack={handleGoHome} />;

      default:
        return <ComingSoon toolName={toolTitle} onBack={handleGoHome} />;
    }
  };

  return (
    <div className="flex flex-col min-h-screen font-sans relative">
      {/* Ticker Bar (Top Overlay) */}
      {showTicker && tickerText && (
          <div className="bg-black/90 text-white py-2 overflow-hidden sticky top-0 z-[60] shadow-md border-b border-white/10" dir="ltr">
              <div className="whitespace-nowrap animate-ticker inline-block min-w-full text-center md:text-lg font-bold px-4">
