            {/* Phrases Section */}
            <div className="neumorphic-outset p-6">
                <div className="mb-4 border-b pb-2">
                    <h3 className="text-xl font-bold text-primary"><i className="fas fa-comment-dots ml-2"></i> عبارات الشريط المتحرك</h3>
