      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (ev) => {
          const imgData = ev.target?.result as string;
          const newFrameId = `custom-${Date.now()}`;
          const newFrame: FrameStyle = {
              id: newFrameId,
              name: 'إطار مخصص',
              previewColor: '#ffffff',
