                          position: 'absolute', 
                          inset: 0, 
                          backgroundImage: `url(${imgData})`, 
                          backgroundSize: '100% 100%', 
                          backgroundRepeat: 'no-repeat',
                          zIndex: 0 
                      }} 
                  />
              ),
              containerStyle: { backgroundColor: 'white', overflow: 'hidden' } // Simple container for image
          };
          setAvailableFrames(prev => [...prev, newFrame]);
          setSelectedFrameId(newFrameId); // Auto-select new frame
      };
      reader.readAsDataURL(file);
      // Reset input
      if (importFrameRef.current) importFrameRef.current.value = '';
  };

  // Helper for robust html2canvas capture
  const captureElement = async (elementId: string) => {
    const element = document.getElementById(elementId);
    if (!element) return null;

    // Critical Fix for Android: Race condition for fonts.
    await Promise.race([
        document.fonts.ready,
        new Promise(resolve => setTimeout(resolve, 1500))
    ]).catch(() => console.warn('Font loading timed out, proceeding with capture...'));

    const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    const scale = isMobile ? 1.0 : 2.0;

    return await html2canvas(element, { 
        scale: scale,
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff',
        logging: false,
        imageTimeout: 5000, 
        removeContainer: true,
        ignoreElements: (node: any) => node.classList?.contains('export-ignore'),
    });
  };

