            }

            const savedPhrases = localStorage.getItem('pause_phrases');
            if (savedPhrases) {
                const parsed = JSON.parse(savedPhrases);
                if (Array.isArray(parsed)) {
                    const cleanPhrases = parsed.map((p: any) => ({
                        id: safeString(p.id) || Date.now().toString(),
