            <span className="hidden md:inline-block w-8 h-px bg-current/30"></span>
            <p>إعداد المستشار الإداري والتربوي إبراهيم دخان</p>
            <span className="hidden md:inline-block w-8 h-px bg-current/30"></span>
        </div>

        {/* TICKER BAR SECTION - Positioned BELOW the text */}
        {tickerText && (
           <div className="w-full max-w-3xl mx-auto mt-2 overflow-hidden rounded-lg bg-black/5 border border-black/10 py-1.5">
                <div className="w-full overflow-hidden">
                    <div className="animate-ticker whitespace-nowrap text-sm font-bold text-heading-text">
                        {tickerText}
                    </div>
                </div>
           </div>
        )}
      </div>
    </header>
  );
};

export default Header;
