    const [logo2, setLogo2] = useState('https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Emblem_of_Yemen.svg/200px-Emblem_of_Yemen.svg.png');

    const logo1Ref = useRef<HTMLInputElement>(null);
    const logo2Ref = useRef<HTMLInputElement>(null);

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, setter: React.Dispatch<React.SetStateAction<string>>) => {
        if (e.target.files && e.target.files[0]) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                if (ev.target?.result) setter(ev.target.result as string);
            };
            reader.readAsDataURL(e.target.files[0]);
        }
    };

    // Custom Export Function to handle multi-page A4 PDF
    const handleExportPDF = async () => {
        const page1 = document.getElementById('template-page-1');
        const page2 = document.getElementById('template-page-2');

        if (!page1 || !page2) return;

        try {
            await Promise.race([document.fonts.ready, new Promise(r => setTimeout(r, 500))]);

            const canvas1 = await html2canvas(page1, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
            const imgData1 = canvas1.toDataURL('image/jpeg', 0.8);

            const canvas2 = await html2canvas(page2, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
            const imgData2 = canvas2.toDataURL('image/jpeg', 0.8);

            const pdf = new jspdf.jsPDF({ orientation: 'p', unit: 'mm', format: 'a4' });
            const pdfWidth = pdf.internal.pageSize.getWidth();
            const pdfHeight = pdf.internal.pageSize.getHeight();

            pdf.addImage(imgData1, 'JPEG', 0, 0, pdfWidth, pdfHeight);
            pdf.addPage();
            pdf.addImage(imgData2, 'JPEG', 0, 0, pdfWidth, pdfHeight);

            pdf.save('exam_template.pdf');
        } catch (error) {
            console.error("PDF Export Error", error);
