      {overlayImage && <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 animate-fadeIn pointer-events-none"><div className="relative max-w-4xl max-h-[90vh] p-4"><img src={overlayImage} alt="Flash" className="max-w-full max-h-full rounded-xl shadow-2xl border-4 border-white/20" /></div></div>}
